// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(address actor, uint96 amount, uint t) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint256 amt = bound(uint256(amount), 1, 100 ether);
        uint256 when = bound(t, 0, 1e12);
        if (block.timestamp > when) when = block.timestamp;

        vm.deal(actor, amt);
        vm.prank(actor);
        c.Put{value: amt}(when);

        (uint unlockTime, uint bal) = c.Acc(actor);
        assertTrue(bal == amt && unlockTime >= block.timestamp && unlockTime <= (when > block.timestamp ? when : block.timestamp));
    }
}
